#!/usr/bin/env bash
set -euo pipefail

ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [[ -z "$ROOT" || ! -f "$ROOT/package.json" || ! -f "$ROOT/app/page.js" ]]; then
  echo "ERROR: Run this file inside the gold-pulse-x-v9 Codespace repository."
  exit 1
fi
cd "$ROOT"

SELF="$(basename "$0")"
OTHER_CHANGES="$(git status --porcelain | grep -v -F "?? $SELF" || true)"
if [[ -n "$OTHER_CHANGES" ]]; then
  echo "ERROR: Repository has other uncommitted changes. Commit or discard them first."
  echo "$OTHER_CHANGES"
  exit 1
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
cat > "$TMP/patch.b64" <<'GPX_PATCH_BASE64'

GPX_PATCH_BASE64
base64 -d "$TMP/patch.b64" > "$TMP/patch.tar.gz"
tar -tzf "$TMP/patch.tar.gz" >/dev/null
tar -xzf "$TMP/patch.tar.gz" -C "$ROOT"
rm -f -- "$ROOT/$SELF"

node scripts/static-check.mjs
node --check app/api/gold/route.js
node --check app/api/health/route.js
node --check app/api/scan/route.js
node --check scripts/set-scan-interval.mjs
python -m json.tool package.json >/dev/null
python -m json.tool public/manifest.webmanifest >/dev/null

git add -A
if git diff --cached --quiet; then
  echo "GOLD PULSE X v9.5 Smart Free is already installed."
  exit 0
fi
if [[ -z "$(git config user.name || true)" ]]; then git config user.name "GOLD PULSE Updater"; fi
if [[ -z "$(git config user.email || true)" ]]; then git config user.email "gold-pulse-updater@users.noreply.github.com"; fi
git commit -m "Upgrade GOLD PULSE X to v9.5 Smart Free"
git push

echo "SUCCESS: v9.5 Smart Free pushed to GitHub. Vercel will deploy automatically."
echo "Check: https://gold-pulse-x-v9.vercel.app/api/health"
